pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: The space left if we pick this bin. Smaller is usually better (Best Fit).
    // post_residual == 0 is ideal (perfect fit).

    let mut score = post_residual as f64;

    // Penalty for creating 'orphaned' space (fragmentation):
    // If we leave space too small for any likely future item (e.g., < 10), it's dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic:
    // If the next item fits into the current post_residual, we should prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Dynamic Time Horizon:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin late in the game.
        score += 40.0 * progress;
    }

    // Global State:
    // If we have many open bins, we want to consolidate into the ones that are already 'fuller'.
    // If the current bin is emptier than the average bin, penalize it.
    if bin_residual < bin_capacity {
        let current_fill = bin_capacity - bin_residual;
        let mean_fill = bin_capacity as f64 - mean_residual;
        if current_fill < mean_fill as u32 {
            score += 15.0;
        }
    }

    // Criticality check:
    // If this is the only bin that fits the current item, avoid opening a new bin at all costs.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the residual space after placement (Best Fit strategy)
    // We want to minimize post_residual to pack bins tightly.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: 
    // Higher as the stream progresses to encourage utilizing existing space.
    if is_new_bin {
        score += 25.0 + (progress * 50.0);
    }

    // Lookahead logic: If the next item is large, avoid leaving small residuals
    // that cannot accommodate the next item (Dead Space avoidance).
    if next_item_size > 0 {
        let next_fit_penalty = if post_residual < next_item_size {
            (next_item_size - post_residual) as f64 * 1.5
        } else {
            0.0
        };
        score += next_fit_penalty;
    }

    // Heuristic coupling: Reward bins that stay close to the mean residual
    // to keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // If this is the only bin that fits the item, heavily prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Non-linear interaction: Penalize creating very small gaps (e.g., < 5)
    // which are likely to remain unused for the rest of the stream.
    if post_residual > 0 && post_residual < 6 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with a non-linear Best-Fit penalty: prioritize tighter fits exponentially.
    let mut score = (post_residual as f64).powf(1.15);

    // 1. Refined Fragmentation Penalty:
    // Targeting "dead-space" gaps that cannot accommodate typical item sizes (1-22).
    if post_residual > 0 && post_residual < 23 {
        score += 54.0 - (post_residual as f64 * 0.7);
    }

    // 2. Predictive Lookahead with Multi-Stage Weighting:
    // If the next item fits, create a strong incentive to preserve that capacity.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item; scale reward by how much space remains.
            score -= 18.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64).sqrt();
        } else {
            // Strong penalty for blocking the next item (preventing future forced new bins).
            score += 34.0;
        }
    }

    // 3. Dynamic Thresholding & New Bin Strategy:
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing fragmentation is high (mean_residual > 20)
        // or if we have very few bins open compared to total_items progress.
        let is_new_bin_needed = (mean_residual > 18.0) || (open_bins_count < (step_index / 15 + 1));
        if fitting_bins_count > 0 && !is_new_bin_needed {
            score += 75.0; 
        } else {
            score = -150.0;
        }
    } else {
        // 4. Global Consolidation Pressure:
        // Increase pressure to consolidate as we approach the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += (post_residual as f64) * progress * 1.2;

        // 5. Scarcity Constraint:
        // If this is the only bin that fits the item, prioritize it to avoid orphan fragments.
        if fitting_bins_count == 1 {
            score -= 65.0;
        }
    }

    // 6. Entropy Normalization:
    // Tighten the variance constraint to encourage uniform bin filling.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.45;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are too small to fit common divisors (10, 20, 25).
    // This forces the algorithm to avoid "orphaned" small spaces that cannot accommodate typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Coupling: If the next item is large, favor bins that have enough space left.
    // If the current post_residual is smaller than the next item, we penalize the bin to prioritize others.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that perfectly accommodate the next item (synergy).
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // 3. Density Balancing: If we are near the end of the stream, prioritize closing bins (minimizing residuals).
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 0.5;

    // 4. New Bin Thresholding: If this is the new-bin candidate (bin_residual == bin_capacity),
    // only choose it if the current best open bin's residual is highly inefficient.
    if bin_residual == bin_capacity {
        // Only open a new bin if the open bins are already too fragmented.
        if open_bins_count > 0 && mean_residual > 20.0 {
            score = 10.0; 
        } else {
            score = 100.0; // Discourage opening new bins unless necessary.
        }
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base weight: Focus on minimizing post_residual (Best Fit principle)
    let mut score = post_residual as f64 * 1.12;

    // 1. Fragment Avoidance: Sharp penalty for "dead zones" (1-18)
    // Refined threshold to avoid small slivers that prevent future large items
    if post_residual > 0 && post_residual <= 18 {
        score += 72.0 - (post_residual as f64 * 1.2);
    }

    // 2. Harmonic/Perfect Fit: Reward perfect fits more aggressively
    if post_residual == 0 {
        score -= 95.0;
    } else if post_residual % 25 == 0 {
        score -= 35.0;
    }

    // 3. Lookahead integration: Prioritize bins that can swallow the next item.
    // Penalty reduced for slack to keep the packing tight.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 82.0 + (slack * 0.35);
    }

    // 4. Strategic Bin Opening: 
    // Dynamic threshold: If mean_residual is low, opening new bins is expensive.
    // Introduce a penalty based on open_bins_count to discourage fragmentation.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 140.0 + (mean_residual * 0.85) + (open_bins_count as f64 * 1.2);
        } else {
            score -= 22.0; 
        }
    }

    // 5. Progression scaling: Shift towards extreme density at the end
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
        score += post_residual as f64 * 2.1;
    }
    score += progress * 42.0;

    // 6. Global load balancing: Penalize divergence from mean_residual
    // Non-linear penalty to force convergence of bin states
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += (dev * 0.5).powf(1.1);
    } else {
        score += dev.abs() * 0.25;
    }

    // 7. Bin Occupancy Pressure:
    // If we have too many open bins, heavily penalize emptier bins to force reuse
    if open_bins_count > 8 {
        score += (bin_residual as f64) * 0.45;
    }

    // 8. Small item grouping: If item is small, prefer bins that are already partially full
    if item_size < 20 && !is_new_bin {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}
